import pandas as pd, re
t=pd.read_csv('table.csv')
src=open('chart.py').read()
ns={}
exec(src.split('data = []')[0],ns)
ed=ns['efficiency_data']
tab={r:sorted(g['Efficiency'].round(2)) for r,g in t.groupby('Region')}
for r,v in ed.items():
    m=[k for k,tv in tab.items() if sorted(v)==tv]
    print(r,'->',m)
for r in tab: print(r,tab[r])
with open('summary.txt') as f: print(f.read())
